<template><AppShell title="积分明细" back><view class="pad"><view class="points-card"><text>可用积分</text><text class="balance">{{data.balance??'—'}}</text><text class="tiny">{{data.sourceRule}}</text></view><StateView :loading="loading" :error="error" :count="data.items?.length||0" title="暂无积分明细" description="免费积分发放与消费后会在这里记录" @retry="load" /><view class="card section" v-for="entry in data.items" :key="entry.id"><view class="row between"><text class="bold">{{entry.note}}</text><text :class="entry.delta>0?'positive':'negative'">{{entry.delta>0?'+':''}}{{entry.delta}}</text></view><view class="row between section"><text class="muted tiny">{{date(entry.createdAt)}}</text><text class="muted tiny">余额 {{entry.balance}}</text></view></view><button v-if="(data.items?.length||0)<data.total" class="ui-button btn outline section" @click="load(true)">加载更多</button></view></AppShell></template>
<script setup>import {ref,watch} from 'vue';import {onShow,onUnload} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import StateView from '../../components/StateView.vue';import {request,requireLogin,date,session} from '../../lib/api';const data=ref({}),loading=ref(false),error=ref('');let page=1,generation=0;onShow(()=>{if(requireLogin())load()});onUnload(resetPrivate);watch(()=>session.token,resetPrivate,{flush:'sync'});function resetPrivate(){generation++;data.value={};page=1;loading.value=false;error.value=''}async function load(more=false){if(loading.value)return;const v=++generation;loading.value=true;error.value='';if(!more)data.value={};try{const next=more?page+1:1,r=await request('/boost/rewards/points','GET',{page:next});if(v===generation){data.value={...r,items:more?[...data.value.items,...r.items]:r.items};page=next}}catch(e){if(v===generation)error.value=e.message}finally{if(v===generation)loading.value=false}}</script>
<style scoped>.points-card{background:#ffe433;border-radius:14px;padding:24px;display:flex;flex-direction:column;gap:10px}.balance{font-size:42px;font-weight:800}.positive{color:#178546;font-weight:700}.negative{font-weight:700}.bold{overflow-wrap:anywhere;padding-right:10px}</style>
